#include <iostream>
#include <print>
#include <string>

int main() {
    std::println("{:<14}{:>6}{:>12}", "Товар", "Кол.", "Сумма");
    std::string name;
    int quantity;
    double price;
    double total = 0;
    while (std::cin >> name >> quantity >> price) {
        double sum = quantity * price;
        total += sum;
        std::println("{:<14}{:>6}{:>12.2f}", name, quantity, sum);
    }
    std::println("{:-<32}", "");
    std::println("{:<20}{:>12.2f}", "Итого", total);
    return 0;
}

