#include <iostream>
#include <print>
#include <string>

std::string in_base(int value, int base) {
    switch (base) {
    case 2:
        return std::format("{:b}", value);
    case 8:
        return std::format("{:o}", value);
    case 16:
        return std::format("{:x}", value);
    default:
        return std::format("{}", value);
    }
}

int main() {
    int n, base;
    std::cin >> n >> base;
    std::size_t width = in_base(n * n, base).size();
    for (int i = 1; i <= n; i++) {
        std::string line;
        for (int j = 1; j <= n; j++) {
            if (j > 1) {
                line += ' ';
            }
            line += std::format("{:>{}}", in_base(i * j, base), width);
        }
        std::println("{}", line);
    }
    return 0;
}

